create table if not exists billing_subscriptions (user_id uuid primary key references platform_users(id) on delete cascade, plan text not null check (plan in ('pro','studio')), status text not null check (status in ('active','non_renewing','past_due','cancelled')), paystack_customer_code text, paystack_subscription_code text unique, paystack_email_token text, current_period_end timestamptz not null, updated_at timestamptz not null default now());
create index if not exists billing_subscriptions_customer on billing_subscriptions(paystack_customer_code);
create table if not exists billing_payments (reference text primary key, user_id uuid not null references platform_users(id) on delete cascade, kind text not null check (kind in ('subscription','renewal','gallery_pass')), plan text check (plan in ('pro','studio')), amount_kobo integer not null check (amount_kobo >= 0), status text not null default 'pending' check (status in ('pending','success','failed')), created_at timestamptz not null default now(), paid_at timestamptz);
create index if not exists billing_payments_user on billing_payments(user_id, created_at desc);
create table if not exists billing_credits (user_id uuid primary key references platform_users(id) on delete cascade, gallery_credits integer not null default 0 check (gallery_credits >= 0));
